function Account(id: byte_array) = require(
	acc.account @? { .id == id },
	"Account '%s' not found".format(id)
);

/*
 * Can be negative
 */
operation dev_give_points(account_id: byte_array, amount: integer){
	val account = Account(account_id);
	dev_op.dev_give_points_(account, amount);
}

operation dev_free_op(account_id: byte_array) {
	// this operation does not cost points in the rate limit
	val account = Account(account_id);
	dev_op.dev_give_points_(account, 1);
	acc.rate_limit(account);
}

/*
 * For complex validation we might not want to use simple "require()"
 * but an error message that is returned. 
 */
struct validation_result {
    valid: boolean;
    error: text? = null;
}

val VALID = validation_result(true, null);

function invalid(error: text) = validation_result(false, error);

@mount('ft3')
module;

query get_version(): text = "4.0.0r";
